        if (money < shop->GetCurrentSellPrice(it->second.first, 1) ||
            (it->second.second > 0 && !inventory->IsSpaceInInventoryForItem(it->second.first) && !IsSpecialCase(it->second.first)) ||
            AlreadyHaveSpecial(it->second.first)) {
